const p = defineEntity.properties;

// mapped superclass (abstract entity that won't have its own table)
const PersonSchema = defineEntity({
  name: 'Person',
  abstract: true,
  properties: {
    mapped1: p.number(),
    mapped2: p.string(),
    toothbrush: () => p.oneToOne(Toothbrush),
  },
});

export const Employee = defineEntity({
  name: 'Employee',
  extends: Person,
  properties: {
    id: p.number().primary(),
    name: p.string(),
  },
});

export const Toothbrush = defineEntity({
  name: 'Toothbrush',
  properties: {
    id: p.number().primary(),
    // ... more fields
  },
});

export class Person extends PersonSchema.class {}
PersonSchema.setClass(Person);
```

> When using `extends` with the `defineEntity + class` pattern, property initializers from the base class run automatically via `super()`. See [Reusing base properties via `extends`](./define-entity.md#extends-initializers) for details.

